namespace NotificationsApp.Models;

public class Notification
{
    public int Id { get; set; }
    public string Message { get; set; } = string.Empty;
    public DateTime Timestamp { get; set; }
}

using NotificationsApp.Models;

namespace NotificationsApp.Services;

public class NotificationService
{
    private int _nextId = 4;
    private readonly List<Notification> _notifications =
    [
        new() { Id = 1, Message = "Welcome to the app!", Timestamp = DateTime.UtcNow.AddMinutes(-30) },
        new() { Id = 2, Message = "Your profile was updated.", Timestamp = DateTime.UtcNow.AddMinutes(-15) },
        new() { Id = 3, Message = "New feature available: dark mode.", Timestamp = DateTime.UtcNow.AddMinutes(-5) },
    ];

    private static readonly string[] SampleMessages =
    [
        "Deployment completed successfully.",
        "A new user signed up.",
        "Server health check passed.",
        "Scheduled backup finished.",
        "New comment on your post.",
        "Your subscription renews soon.",
    ];

    /// <summary>Returns all notifications.</summary>
    public Task<List<Notification>> GetNotificationsAsync()
        => Task.FromResult(_notifications.ToList());

    /// <summary>Returns notifications added after the given ID (simulates new arrivals).</summary>
    public Task<List<Notification>> GetNotificationsSinceAsync(int lastId)
    {
        // Each call randomly decides whether to produce a new notification.
        if (Random.Shared.Next(3) == 0) // ~33 % chance per poll
        {
            var msg = SampleMessages[Random.Shared.Next(SampleMessages.Length)];
            _notifications.Add(new Notification
            {
                Id = _nextId++,
                Message = msg,
                Timestamp = DateTime.UtcNow,
            });
        }

        var newer = _notifications.Where(n => n.Id > lastId).ToList();
        return Task.FromResult(newer);
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using NotificationsApp.Models
@using NotificationsApp.Services
@inject NotificationService NotificationService
@implements IAsyncDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    @if (notifications is not null)
    {
        <span class="badge bg-primary rounded-pill ms-2">@notifications.Count</span>
    }
</h1>

@if (notifications is null)
{
    <p><em>Loading notifications…</em></p>
}
else if (notifications.Count == 0)
{
    <p>No notifications yet.</p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private List<Notification>? notifications;
    private CancellationTokenSource? _cts;
    private int _lastId;

    // Persist the initial data across the prerender → interactive boundary
    // so OnInitializedAsync does NOT re-fetch on the second (interactive) render.
    [PersistentState]
    public List<Notification>? PersistedNotifications { get; set; }

    protected override async Task OnInitializedAsync()
    {
        // ??= ensures we only hit the service during the prerender pass.
        // On the interactive render the value is already restored from persisted state.
        PersistedNotifications ??= await NotificationService.GetNotificationsAsync();
        notifications = PersistedNotifications;
        _lastId = notifications.Max(n => n.Id);
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // OnAfterRender is never called during prerender, so this is
            // guaranteed to run only once the page is truly interactive.
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct);

            var newer = await NotificationService.GetNotificationsSinceAsync(_lastId);
            if (newer.Count > 0)
            {
                notifications!.AddRange(newer);
                _lastId = newer.Max(n => n.Id);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

